// Mona Sans (SIL Open Font License), the site's own font, as static ExtraBold and Medium cuts for the story pictures
// (Install 29). The picture renderer can't read the web font file, so these are kept here as data.
import 'server-only'
const from64 = (s) => { const b = Buffer.from(s, 'base64'); return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength) }
export const FONTS = () => [
  { name: 'Mona', weight: 800, style: 'normal', data: from64('') },
  { name: 'Mona', weight: 500, style: 'normal', data: from64('') },
]
